CREATE DATABASE IF NOT EXISTS coach_pronos_media CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE coach_pronos_media;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','editor','viewer') NOT NULL DEFAULT 'viewer',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,last_login_at DATETIME NULL,INDEX idx_users_active(is_active),INDEX idx_users_role(role));
CREATE TABLE IF NOT EXISTS folders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_folder_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,type ENUM('image','video') NOT NULL,folder_id BIGINT UNSIGNED NULL,summary TEXT,original_name VARCHAR(255),stored_name VARCHAR(191) NOT NULL UNIQUE,relative_path VARCHAR(1000) NOT NULL,mime_type VARCHAR(120),size_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,favorite TINYINT(1) NOT NULL DEFAULT 0,deleted_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_asset_folder FOREIGN KEY(folder_id) REFERENCES folders(id) ON DELETE SET NULL,CONSTRAINT fk_asset_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_assets_type(type),INDEX idx_assets_folder(folder_id),INDEX idx_assets_deleted(deleted_at),INDEX idx_assets_created(created_at),INDEX idx_assets_favorite(favorite),INDEX idx_assets_created_by(created_by));
CREATE TABLE IF NOT EXISTS favorites (user_id BIGINT UNSIGNED NOT NULL,asset_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,asset_id),CONSTRAINT fk_fav_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_fav_asset FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,asset_id BIGINT UNSIGNED NULL,details VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_log_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_log_asset FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE SET NULL,INDEX idx_logs_created(created_at),INDEX idx_logs_user(user_id));
INSERT IGNORE INTO folders(name) VALUES ('Mini série'),('Chansons'),('Débat'),('Formation');
